import sys
from datetime import date


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def main():
    lines = [line.split() for line in sys.stdin if line.strip()]
    ref = parse(lines[0][0])
    counts = {"child": 0, "teen": 0, "adult": 0, "senior": 0}
    for name, born in lines[1:]:
        birth_date = parse(born)
        age = ref.year - birth_date.year
        if ref.month < birth_date.month or (
            ref.month == birth_date.month and ref.day < birth_date.day
        ):
            age -= 1
        if age <= 12:
            group = "child"
        elif age <= 17:
            group = "teen"
        elif age <= 64:
            group = "adult"
        else:
            group = "senior"
        counts[group] += 1
        print(f"{name} {age} {group}")
    for group in ["child", "teen", "adult", "senior"]:
        print(f"{group} {counts[group]}")


if __name__ == "__main__":
    main()
